FOLD = 0
HELD_USERS = (1, 2, 3)
EXPECTED_HELD_ROWS = 477
ROWS = 2931
CLASSES = 40
SOURCE_CLASSES = 120
FRAMES = 64
EPOCHS = 24
BATCH_SIZE = 32
EXPECTED_BATCHES_PER_EPOCH = 77
EXPECTED_OPTIMIZER_STEPS_PER_ARM = 1848
RUNTIME_SEED = 20260823
INIT_SEEDS = {'joint': 2026082301, 'bone': 2026082302}
PAIR_SEEDS = {'joint': 20261823, 'bone': 20262823}
BACKBONE_LR = 0.0005
HEAD_LR = 0.001
BACKBONE_MIN_LR = 1e-05
HEAD_MIN_LR = 2e-05
WEIGHT_DECAY = 0.05
LABEL_SMOOTHING = 0.1
GRAD_CLIP = 1.0
CHECKPOINT_PAIR_LIMIT_BYTES = 20000000
INFERENCE_BUNDLE_LIMIT_BYTES = 100000000
MODEL_CONFIG: dict[str, Any] = {'num_classes': CLASSES, 'num_people': 2, 'num_frames': 64, 'num_points': 24, 'kernel_size': 7, 'num_heads': 32, 'type_1_size': (8, 8), 'type_2_size': (8, 12), 'type_3_size': (8, 8), 'type_4_size': (8, 12), 'attn_drop': 0.5, 'head_drop': 0.0, 'drop': 0.0, 'rel': True, 'drop_path': 0.2, 'mlp_ratio': 4.0, 'index_t': True, 'global_pool': 'avg'}

def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open('rb') as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b''):
            digest.update(block)
    return digest.hexdigest()

def write_json(path: Path, value: Any) -> None:
    path.write_text(json.dumps(value, indent=2, sort_keys=True) + '\n', encoding='utf-8')

def file_fact(path: Path) -> dict[str, Any]:
    return {'path': path.name, 'bytes': path.stat().st_size, 'sha256': sha256_file(path)}

def canonical_tensor_digest(items: Iterable[tuple[str, torch.Tensor]]) -> str:
    digest = hashlib.sha256()
    for name, tensor in sorted(items, key=lambda item: item[0]):
        value = tensor.detach().cpu().contiguous()
        digest.update(name.encode('utf-8') + b'\x00')
        digest.update(str(value.dtype).encode('ascii') + b'\x00')
        digest.update(json.dumps(list(value.shape), separators=(',', ':')).encode('ascii') + b'\x00')
        digest.update(value.numpy().tobytes(order='C'))
    return digest.hexdigest()

def seed_everything(seed: int) -> None:
    random.seed(seed)
    np.random.seed(seed % 2 ** 32)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)
    torch.use_deterministic_algorithms(True)
    torch.backends.cudnn.benchmark = False
    torch.backends.cudnn.deterministic = True
    if hasattr(torch.backends.cuda.matmul, 'allow_tf32'):
        torch.backends.cuda.matmul.allow_tf32 = False
    if hasattr(torch.backends.cudnn, 'allow_tf32'):
        torch.backends.cudnn.allow_tf32 = False

def stateless_augmentation_seed(modality: str, epoch_index: int, row_index: int,
                                fold: int | None = None) -> int:
    # The fold must be passed in by callers that run inside DataLoader workers. A spawned
    # worker re-imports this module and therefore sees the module-level FOLD default, not
    # the value the parent assigned, which silently produced fold 0's augmentation for
    # every fold. Falling back to the global keeps the in-process call sites unchanged.
    fold = FOLD if fold is None else fold
    text = f'skateformer-v1|arm-independent|{fold}|{modality}|{epoch_index}|{row_index}'
    return int(hashlib.sha256(text.encode('utf-8')).hexdigest(), 16) % 2 ** 32

def check_probabilities(name: str, probabilities: np.ndarray, rows: int) -> None:
    if probabilities.shape != (rows, CLASSES):
        raise RuntimeError(f'{name} shape drift: {probabilities.shape}')
    if probabilities.dtype != np.float32 or not np.isfinite(probabilities).all():
        raise RuntimeError(f'{name} must be finite float32')
    error = float(np.max(np.abs(probabilities.sum(axis=1, dtype=np.float64) - 1.0)))
    if error > 2e-05:
        raise RuntimeError(f'{name} normalization error: {error}')

@dataclass(frozen=True)
class Metadata:
    labels: np.ndarray
    users: np.ndarray
    n_valid: np.ndarray
    groups: tuple[str, ...]

def load_train_only_assets(asset_root: Path) -> tuple[np.ndarray, Metadata]:
    with np.load(asset_root / 'train_only_skeleton.npz', allow_pickle=False) as archive:
        if archive.files != ['train', 'train_n_valid']:
            raise RuntimeError(f'sanitized NPZ key drift: {archive.files}')
        train = np.asarray(archive['train'], dtype=np.float32)
        archive_n_valid = np.asarray(archive['train_n_valid'], dtype=np.int64)
    if train.shape != (ROWS, 128, 17, 3) or archive_n_valid.shape != (ROWS,):
        raise RuntimeError(f'train-only shape drift: {train.shape}, {archive_n_valid.shape}')
    if not np.isfinite(train).all():
        raise RuntimeError('non-finite target training skeleton')
    labels: list[int] = []
    users: list[int] = []
    n_valid: list[int] = []
    groups: list[str] = []
    with (asset_root / 'skeleton_train_meta.csv').open('r', encoding='utf-8', newline='') as handle:
        reader = csv.DictReader(handle)
        wanted = ['group', 'action', 'user', 'trial', 'label', 'n_valid']
        if reader.fieldnames != wanted:
            raise RuntimeError(f'metadata columns drift: {reader.fieldnames}')
        for row in reader:
            groups.append(row['group'])
            labels.append(int(row['label']))
            user_text = row['user']
            if not user_text.startswith('user'):
                raise RuntimeError(f'invalid user: {user_text}')
            users.append(int(user_text[4:]))
            n_valid.append(int(row['n_valid']))
    metadata = Metadata(labels=np.asarray(labels, dtype=np.int64), users=np.asarray(users, dtype=np.int64), n_valid=np.asarray(n_valid, dtype=np.int64), groups=tuple(groups))
    if metadata.labels.shape != (ROWS,) or metadata.users.shape != (ROWS,):
        raise RuntimeError('metadata row-count drift')
    if not np.array_equal(metadata.n_valid, archive_n_valid):
        raise RuntimeError('metadata/archive valid-length mismatch')
    if np.any((metadata.labels < 0) | (metadata.labels >= CLASSES)):
        raise RuntimeError('label range drift')
    if np.any((metadata.n_valid < 1) | (metadata.n_valid > 128)):
        raise RuntimeError('valid-frame range drift')
    if len(set(metadata.groups)) != ROWS:
        raise RuntimeError('training group identifiers are not unique')
    held = np.flatnonzero(np.isin(metadata.users, np.asarray(HELD_USERS, dtype=np.int64)))
    if held.size != EXPECTED_HELD_ROWS:
        raise RuntimeError(f'canonical fold0 row count drift: {held.size}')
    return (train, metadata)

def prepare_raw_ntu(train: np.ndarray, metadata: Metadata, adapter: Any) -> np.ndarray:
    raw = np.zeros((ROWS, 3, 128, 25, 2), dtype=np.float32)
    for index in range(ROWS):
        valid = int(metadata.n_valid[index])
        sequence = train[index, :valid]
        pseudo = adapter.map_h36m17_to_ntu25(sequence)
        prepared = adapter.source_native_translate_and_duplicate(pseudo)
        if prepared.shape != (3, valid, 25, 2) or not np.isfinite(prepared).all():
            raise RuntimeError(f'adapter output drift at row {index}')
        raw[index, :, :valid] = prepared
    return raw

def valid_crop_uniform_compat(data_numpy: np.ndarray, valid_frame_num: int, window: int=FRAMES, threshold: int=FRAMES) -> tuple[np.ndarray, np.ndarray]:
    """Exact official multi-interval algorithm with NumPy-2 scalar compatibility.

    The pinned official code obtains ``p`` as a one-element array and converts that
    array with ``int(...)``.  NumPy 2 rejects the formerly permitted implicit array to
    scalar conversion.  ``float(np.random.rand())`` consumes the identical single RNG
    draw and leaves every subsequent branch and draw unchanged.
    """
    channels, _frames, joints, people = data_numpy.shape
    valid_size = int(valid_frame_num)
    p = float(np.random.rand()) * 0.5 + 0.5
    cropped_length = int(min(max(int(math.floor(valid_size * p)), threshold), valid_size))
    bias = int(np.random.randint(0, valid_size - cropped_length + 1))
    if cropped_length < window:
        indices = np.arange(cropped_length, dtype=np.int64)
    elif window <= cropped_length < 2 * window:
        basic = np.arange(window, dtype=np.int64)
        selected = np.random.choice(window + 1, cropped_length - window, replace=False)
        offset = np.zeros(window + 1, dtype=np.int64)
        offset[selected] = 1
        offset = np.cumsum(offset)
        indices = basic + offset[:-1]
    else:
        boundaries = np.asarray([i * cropped_length // window for i in range(window + 1)], dtype=np.int64)
        bin_sizes = np.diff(boundaries)
        starts = boundaries[:window]
        offsets = np.random.randint(bin_sizes)
        indices = starts + offsets
    indices = indices + bias
    data = torch.as_tensor(data_numpy[:, indices], dtype=torch.float32)
    index_t = torch.as_tensor(indices, dtype=torch.float32)
    data = data.permute(2, 3, 0, 1).contiguous().view(joints * people, channels, len(indices))
    if len(indices) != window:
        data = F.interpolate(data, size=window, mode='linear', align_corners=False)
        index_t = F.interpolate(index_t[None, None, :], size=window, mode='linear', align_corners=False).squeeze(0).squeeze(0)
    clip = data.contiguous().view(joints, people, channels, window)
    clip = clip.permute(2, 3, 0, 1).contiguous().numpy()
    normalized_time = 2.0 * index_t / float(valid_size) - 1.0
    return (clip, normalized_time.numpy())

class SkateDataset(Dataset[tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]]):

    def __init__(self, raw_ntu: np.ndarray, metadata: Metadata, modality: str, training: bool,
                 adapter: Any, official_tools: Any, fold: int | None = None) -> None:
        if modality not in ('joint', 'bone'):
            raise ValueError(modality)
        self.raw_ntu = raw_ntu
        self.metadata = metadata
        self.modality = modality
        self.training = bool(training)
        self.adapter = adapter
        self.tools = official_tools
        # Captured in the parent so spawned workers use the correct fold.
        self.fold = FOLD if fold is None else int(fold)
        self.epoch_index = 0

    # DataLoader workers are forked on Linux, which needs no pickling. On a spawn
    # platform the dataset is pickled instead, and module objects cannot be pickled.
    # Carry the two vendor modules by name and re-import them in the worker: the worker
    # ends up with the identical modules, so sampling and numerics are unchanged.
    def __getstate__(self) -> dict:
        import os as _os
        state = self.__dict__.copy()
        state['adapter'] = self.adapter.__name__
        state['tools'] = self.tools.__name__
        # A spawned worker does not inherit runtime sys.path edits, so carry the
        # directories these modules were imported from alongside their names.
        state['_vendor_search_paths'] = [
            _os.path.dirname(_os.path.abspath(m.__file__))
            for m in (self.adapter, self.tools) if getattr(m, '__file__', None)]
        state['_vendor_modules_by_name'] = True
        return state

    def __setstate__(self, state: dict) -> None:
        if state.pop('_vendor_modules_by_name', False):
            import importlib, sys as _sys
            for directory in state.pop('_vendor_search_paths', []):
                if directory and directory not in _sys.path:
                    _sys.path.insert(0, directory)
            state['adapter'] = importlib.import_module(state['adapter'])
            state['tools'] = importlib.import_module(state['tools'])
        state.pop('_vendor_search_paths', None)
        self.__dict__.update(state)

    def __len__(self) -> int:
        return ROWS

    def set_epoch(self, epoch_index: int) -> None:
        self.epoch_index = int(epoch_index)

    def _official_augment(self, clip: np.ndarray) -> np.ndarray:
        probability = np.random.rand(1)
        if probability < 0.5:
            if np.random.rand(1) < 0.5:
                clip = clip[:, :, :, np.asarray([1, 0], dtype=np.int64)]
            clip = self.tools.shear(clip, p=0.5)
            clip = self.tools.rotate(clip, p=0.5)
            clip = self.tools.scale(clip, p=0.5)
            clip = self.tools.spatial_flip(clip, p=0.5)
            clip = self.tools.drop_axis(clip, p=0.5)
            clip = self.tools.drop_joint(clip, p=0.5)
        return np.asarray(clip, dtype=np.float32)

    def __getitem__(self, index: int) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
        valid = int(self.metadata.n_valid[index])
        source = self.raw_ntu[index]
        if self.training:
            seed = stateless_augmentation_seed(self.modality, self.epoch_index, int(index), self.fold)
            random.seed(seed)
            np.random.seed(seed)
            clip, index_t = valid_crop_uniform_compat(source, valid, FRAMES, FRAMES)
            clip = self._official_augment(clip)
        else:
            clip, index_t = self.adapter.crop_resize_eval(source[:, :valid])
        if self.modality == 'bone':
            clip = self.adapter.joint_to_bone(clip)
        clip = self.adapter.partition_joints(clip)
        if clip.shape != (3, FRAMES, 24, 2):
            raise RuntimeError(f'prepared clip shape drift at row {index}: {clip.shape}')
        return (torch.from_numpy(np.ascontiguousarray(clip)).float(), torch.from_numpy(np.ascontiguousarray(index_t)).float(), torch.tensor(int(self.metadata.labels[index]), dtype=torch.long), torch.tensor(int(index), dtype=torch.long))

def worker_init(worker_id: int) -> None:
    seed = (RUNTIME_SEED + 7000 + int(worker_id)) % 2 ** 32
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)

def make_train_loader(dataset: SkateDataset, train_indices: np.ndarray, epoch_index: int, device: torch.device) -> DataLoader:
    dataset.set_epoch(epoch_index)
    generator = torch.Generator()
    generator.manual_seed(2026082310 + 100 * FOLD + epoch_index)
    sampler = SubsetRandomSampler(train_indices.tolist(), generator=generator)
    return DataLoader(dataset, batch_size=BATCH_SIZE, sampler=sampler, num_workers=2, worker_init_fn=worker_init, pin_memory=device.type == 'cuda', drop_last=False, persistent_workers=False)

def make_held_loader(dataset: SkateDataset, held_indices: np.ndarray, device: torch.device) -> DataLoader:
    return DataLoader(Subset(dataset, held_indices.tolist()), batch_size=BATCH_SIZE, shuffle=False, num_workers=2, worker_init_fn=worker_init, pin_memory=device.type == 'cuda', drop_last=False, persistent_workers=False)

def instantiate_model(model_module: Any, num_classes: int=CLASSES) -> torch.nn.Module:
    arguments = dict(MODEL_CONFIG)
    arguments['num_classes'] = int(num_classes)
    return model_module.SkateFormer_(**arguments)

def load_source_state(path: Path) -> dict[str, torch.Tensor]:
    from safetensors.torch import load_file
    state = load_file(str(path), device='cpu')
    if not isinstance(state, dict) or len(state) != 214:
        raise RuntimeError(f'source state entry-count drift: {len(state)}')
    if any((not isinstance(name, str) or not torch.is_tensor(value) for name, value in state.items())):
        raise RuntimeError('invalid source state entry')
    return {name: value.detach().cpu().contiguous() for name, value in state.items()}

def validate_source_state(model_module: Any, source_state: Mapping[str, torch.Tensor]) -> None:
    seed_everything(RUNTIME_SEED)
    source_model = instantiate_model(model_module, SOURCE_CLASSES)
    target = source_model.state_dict()
    if set(target) != set(source_state):
        raise RuntimeError('official source model/state key drift')
    for name in target:
        if tuple(target[name].shape) != tuple(source_state[name].shape):
            raise RuntimeError(f'official source tensor shape drift: {name}')
    source_model.load_state_dict(source_state, strict=True)
    del source_model

def overlay_source_state(base: Mapping[str, torch.Tensor], source_state: Mapping[str, torch.Tensor], modality: str) -> tuple[dict[str, torch.Tensor], dict[str, Any]]:
    """Apply the locked exact-name/exact-shape 212+2 transfer rule.

    Kept independent of model construction so the critical rule can be exercised with
    purely synthetic state dictionaries by the smoke test.
    """
    if set(base) != set(source_state):
        raise RuntimeError(f'{modality} target/source key drift')
    treatment = {name: value.detach().cpu().clone() for name, value in base.items()}
    loaded: list[dict[str, Any]] = []
    excluded: list[dict[str, Any]] = []
    for name, source in source_state.items():
        if name in ('head.weight', 'head.bias'):
            excluded.append({'name': name, 'source_shape': list(source.shape), 'reason': '40-class target head'})
            continue
        if tuple(source.shape) != tuple(base[name].shape):
            raise RuntimeError(f'unexpected eligible shape mismatch: {modality}/{name}')
        treatment[name] = source.to(dtype=base[name].dtype).clone()
        loaded.append({'name': name, 'shape': list(source.shape), 'numel': int(source.numel())})
    if len(loaded) != 212 or {entry['name'] for entry in excluded} != {'head.weight', 'head.bias'}:
        raise RuntimeError(f'locked 212+2 load contract failed for {modality}')
    manifest = {'modality': modality, 'source_entries': len(source_state), 'loaded_entries': len(loaded), 'excluded_entries': excluded, 'loaded_elements': int(sum((entry['numel'] for entry in loaded))), 'base_state_sha256': canonical_tensor_digest(base.items()), 'treatment_initial_state_sha256': canonical_tensor_digest(treatment.items()), 'source_state_sha256': canonical_tensor_digest(source_state.items()), 'loaded': loaded}
    return (treatment, manifest)

def build_initial_states(model_module: Any, source_state: Mapping[str, torch.Tensor], modality: str) -> tuple[dict[str, torch.Tensor], dict[str, torch.Tensor], dict[str, Any]]:
    seed_everything(INIT_SEEDS[modality])
    model = instantiate_model(model_module, CLASSES)
    base = {name: value.detach().cpu().clone() for name, value in model.state_dict().items()}
    treatment, manifest = overlay_source_state(base, source_state, modality)
    model.load_state_dict(base, strict=True)
    model.load_state_dict(treatment, strict=True)
    del model
    return (base, treatment, manifest)

def is_no_weight_decay(name: str, parameter: torch.Tensor) -> bool:
    return parameter.ndim <= 1 or name == 'joint_person_embedding' or 'relative_position_bias_table' in name

def optimizer_groups(model: torch.nn.Module) -> list[dict[str, Any]]:
    buckets: dict[tuple[str, str], list[torch.nn.Parameter]] = {('backbone', 'decay'): [], ('backbone', 'no_decay'): [], ('head', 'decay'): [], ('head', 'no_decay'): []}
    for name, parameter in model.named_parameters():
        location = 'head' if name.startswith('head.') else 'backbone'
        decay = 'no_decay' if is_no_weight_decay(name, parameter) else 'decay'
        buckets[location, decay].append(parameter)
    groups: list[dict[str, Any]] = []
    for (location, decay), parameters in buckets.items():
        if not parameters:
            continue
        base_lr = HEAD_LR if location == 'head' else BACKBONE_LR
        min_lr = HEAD_MIN_LR if location == 'head' else BACKBONE_MIN_LR
        groups.append({'params': parameters, 'lr': base_lr, 'weight_decay': 0.0 if decay == 'no_decay' else WEIGHT_DECAY, 'locked_name': f'{location}_{decay}', 'base_lr': base_lr, 'min_lr': min_lr})
    if sum((len(group['params']) for group in groups)) != len(list(model.parameters())):
        raise RuntimeError('optimizer parameter partition drift')
    return groups

def assert_fp32_parameters_and_gradients(model: torch.nn.Module, context: str) -> tuple[int, int]:
    floating_parameters = 0
    floating_gradients = 0
    for name, parameter in model.named_parameters():
        if parameter.is_floating_point():
            floating_parameters += 1
            if parameter.dtype != torch.float32:
                raise RuntimeError(f'non-float32 model parameter: {context}/{name}/{parameter.dtype}')
        gradient = parameter.grad
        if gradient is not None and gradient.is_floating_point():
            floating_gradients += 1
            if gradient.dtype != torch.float32:
                raise RuntimeError(f'non-float32 model gradient: {context}/{name}/{gradient.dtype}')
    if floating_parameters == 0:
        raise RuntimeError(f'no floating model parameters: {context}')
    return (floating_parameters, floating_gradients)

def assert_fp32_optimizer_state(optimizer: torch.optim.Optimizer, context: str) -> int:
    floating_state_tensors = 0
    for parameter_state in optimizer.state.values():
        for state_name, value in parameter_state.items():
            if isinstance(value, torch.Tensor) and value.is_floating_point():
                floating_state_tensors += 1
                if value.dtype != torch.float32:
                    raise RuntimeError(f'non-float32 optimizer state: {context}/{state_name}/{value.dtype}')
    if floating_state_tensors == 0:
        raise RuntimeError(f'no floating optimizer state tensors after step: {context}')
    return floating_state_tensors

def learning_rate_at_epoch(base_lr: float, minimum_lr: float, epoch_index: int) -> float:
    if epoch_index == 0:
        return 0.1 * base_lr
    if epoch_index == 1:
        return base_lr
    progress = (epoch_index - 1) / (EPOCHS - 2)
    cosine = 0.5 * (1.0 + math.cos(math.pi * progress))
    return minimum_lr + (base_lr - minimum_lr) * cosine

def train_final_state(name: str, modality: str, initial_state: Mapping[str, torch.Tensor], model_module: Any, dataset: SkateDataset, train_indices: np.ndarray, device: torch.device) -> tuple[dict[str, torch.Tensor], dict[str, Any]]:
    seed_everything(PAIR_SEEDS[modality])
    model = instantiate_model(model_module, CLASSES)
    model.load_state_dict(initial_state, strict=True)
    model.float().to(device)
    initial_parameter_count, initial_gradient_count = assert_fp32_parameters_and_gradients(model, f'{name}/initial')
    if initial_gradient_count != 0:
        raise RuntimeError(f'unexpected initial gradients: {name}/{initial_gradient_count}')
    groups = optimizer_groups(model)
    optimizer = torch.optim.AdamW(groups, betas=(0.9, 0.999), eps=1e-08)
    history: list[dict[str, Any]] = []
    optimizer_steps = 0
    parameter_dtype_checks = 0
    gradient_dtype_checks = 0
    optimizer_state_dtype_checks = 0
    last_floating_gradient_count = 0
    last_floating_optimizer_state_count = 0
    started = time.time()
    for epoch_index in range(EPOCHS):
        for group in optimizer.param_groups:
            group['lr'] = learning_rate_at_epoch(float(group['base_lr']), float(group['min_lr']), epoch_index)
        model.train()
        loader = make_train_loader(dataset, train_indices, epoch_index, device)
        running_loss = 0.0
        seen = 0
        epoch_batches = 0
        epoch_started = time.time()
        for features, index_t, labels, _rows in loader:
            features = features.to(device, dtype=torch.float32, non_blocking=True)
            index_t = index_t.to(device, non_blocking=True)
            labels = labels.to(device, non_blocking=True)
            optimizer.zero_grad(set_to_none=True)
            logits = model(features, index_t)
            if logits.dtype != torch.float32:
                raise RuntimeError(f'non-float32 training logits: {name}/epoch{epoch_index + 1}')
            loss = F.cross_entropy(logits, labels, label_smoothing=LABEL_SMOOTHING)
            if loss.dtype != torch.float32:
                raise RuntimeError(f'non-float32 training loss: {name}/epoch{epoch_index + 1}')
            if not bool(torch.isfinite(loss).item()):
                raise RuntimeError(f'non-finite training loss: {name}/epoch{epoch_index + 1}')
            loss.backward()
            floating_parameter_count, floating_gradient_count = assert_fp32_parameters_and_gradients(model, f'{name}/epoch{epoch_index + 1}/pre_step{optimizer_steps + 1}')
            if floating_parameter_count != initial_parameter_count:
                raise RuntimeError(f'floating parameter-count drift: {name}')
            if floating_gradient_count == 0:
                raise RuntimeError(f'no floating gradients before optimizer step: {name}')
            parameter_dtype_checks += 1
            gradient_dtype_checks += 1
            last_floating_gradient_count = floating_gradient_count
            gradient_norm = torch.nn.utils.clip_grad_norm_(model.parameters(), GRAD_CLIP)
            if not bool(torch.isfinite(gradient_norm).item()):
                raise RuntimeError(f'non-finite gradient norm: {name}/epoch{epoch_index + 1}')
            optimizer.step()
            last_floating_optimizer_state_count = assert_fp32_optimizer_state(optimizer, f'{name}/epoch{epoch_index + 1}/post_step{optimizer_steps + 1}')
            optimizer_state_dtype_checks += 1
            optimizer_steps += 1
            epoch_batches += 1
            count = int(labels.numel())
            running_loss += float(loss.detach().cpu()) * count
            seen += count
        if seen != int(train_indices.size):
            raise RuntimeError(f'training coverage drift for {name}: {seen}')
        if epoch_batches != EXPECTED_BATCHES_PER_EPOCH:
            raise RuntimeError(f'training batch-count drift for {name}/epoch{epoch_index + 1}: {epoch_batches}')
        lr_report = {str(group['locked_name']): float(group['lr']) for group in optimizer.param_groups}
        epoch_report = {'epoch': epoch_index + 1, 'mean_training_loss': running_loss / seen, 'examples': seen, 'batches': epoch_batches, 'optimizer_steps_cumulative': optimizer_steps, 'learning_rates': lr_report, 'seconds': time.time() - epoch_started}
        history.append(epoch_report)
        print(f"{name} epoch={epoch_index + 1:02d}/{EPOCHS} loss={epoch_report['mean_training_loss']:.6f} seconds={epoch_report['seconds']:.1f}", flush=True)
    if optimizer_steps != EXPECTED_OPTIMIZER_STEPS_PER_ARM:
        raise RuntimeError(f'optimizer-step drift for {name}: {optimizer_steps}')
    if parameter_dtype_checks != EXPECTED_OPTIMIZER_STEPS_PER_ARM or gradient_dtype_checks != EXPECTED_OPTIMIZER_STEPS_PER_ARM or optimizer_state_dtype_checks != EXPECTED_OPTIMIZER_STEPS_PER_ARM:
        raise RuntimeError(f'FP32 mechanical dtype-check coverage drift: {name}')
    final_parameter_count, _final_gradient_count = assert_fp32_parameters_and_gradients(model, f'{name}/final')
    if final_parameter_count != initial_parameter_count:
        raise RuntimeError(f'final floating parameter-count drift: {name}')
    final_state = {name_: value.detach().cpu().clone() for name_, value in model.state_dict().items()}
    report = {'name': name, 'modality': modality, 'training_precision': 'float32', 'model_and_input_dtype': 'torch.float32', 'forward_dtype': 'torch.float32', 'loss_dtype': 'torch.float32', 'backward_gradient_dtype': 'torch.float32', 'optimizer_state_dtype': 'torch.float32', 'floating_model_parameters_checked': initial_parameter_count, 'last_floating_gradients_checked': last_floating_gradient_count, 'last_floating_optimizer_state_tensors_checked': last_floating_optimizer_state_count, 'parameter_dtype_checks': parameter_dtype_checks, 'gradient_dtype_checks': gradient_dtype_checks, 'optimizer_state_dtype_checks': optimizer_state_dtype_checks, 'autocast_enabled': False, 'grad_scaler_enabled': False, 'epochs_completed': EPOCHS, 'optimizer_steps': optimizer_steps, 'skipped_optimizer_steps': 0, 'held_evaluations_during_training': 0, 'history': history, 'final_state_sha256': canonical_tensor_digest(final_state.items()), 'elapsed_seconds': time.time() - started}
    del optimizer, model
    if device.type == 'cuda':
        torch.cuda.empty_cache()
    gc.collect()
    return (final_state, report)

def make_symmetric_float16_replay(context: str, state: Mapping[str, torch.Tensor], checkpoint_path: Path | None) -> tuple[dict[str, torch.Tensor], dict[str, Any]]:
    """Apply one full safetensors FP16 replay rule to every primary-comparison arm.

    Control states are serialized and reloaded in memory.  Treatment states use the
    identical serialization bytes, persist those bytes, and are then reloaded from the
    persisted file.  Thus both arms have identical dtype/serialization semantics while
    treatment probabilities still correspond exactly to deployable checkpoints.
    """
    from safetensors.torch import load, load_file, save
    if len(state) != 214:
        raise RuntimeError(f'{context} state entry drift before replay: {len(state)}')
    compact: dict[str, torch.Tensor] = {}
    for name, value in state.items():
        tensor = value.detach().cpu().contiguous()
        if tensor.is_floating_point() and (not bool(torch.isfinite(tensor).all())):
            raise RuntimeError(f'non-finite state before FP16 replay: {context}/{name}')
        compact[name] = tensor.half() if tensor.is_floating_point() else tensor.clone()
        if compact[name].is_floating_point() and (not bool(torch.isfinite(compact[name]).all())):
            raise RuntimeError(f'float16 overflow during replay: {context}/{name}')
    serialized = save(compact)
    replay = load(serialized)
    persisted = checkpoint_path is not None
    if checkpoint_path is not None:
        checkpoint_path.write_bytes(serialized)
        replay = load_file(str(checkpoint_path), device='cpu')
        if checkpoint_path.read_bytes() != serialized:
            raise RuntimeError(f'persisted replay bytes drift: {context}')
    if set(replay) != set(state):
        raise RuntimeError(f'replay key drift: {context}')
    floating_entries = 0
    integer_entries = 0
    for name in state:
        if tuple(replay[name].shape) != tuple(state[name].shape):
            raise RuntimeError(f'replay shape drift: {context}/{name}')
        if replay[name].is_floating_point() and replay[name].dtype != torch.float16:
            raise RuntimeError(f'replay floating dtype drift: {context}/{name}')
        if replay[name].is_floating_point():
            floating_entries += 1
            if not bool(torch.isfinite(replay[name]).all()):
                raise RuntimeError(f'non-finite FP16 replay: {context}/{name}')
        else:
            integer_entries += 1
    replay_state = {name: value.detach().cpu().contiguous() for name, value in replay.items()}
    facts = {'context': context, 'entries': len(replay_state), 'floating_entries': floating_entries, 'integer_entries': integer_entries, 'floating_dtype': 'torch.float16', 'all_floating_values_finite': True, 'serialized_bytes': len(serialized), 'persisted_treatment_checkpoint': persisted, 'source_fp32_state_sha256': canonical_tensor_digest(state.items()), 'evaluation_replay_sha256': canonical_tensor_digest(replay_state.items())}
    return (replay_state, facts)

def evaluate_state_once(name: str, state: Mapping[str, torch.Tensor], model_module: Any, held_loader: DataLoader, expected_indices: np.ndarray, device: torch.device) -> np.ndarray:
    model = instantiate_model(model_module, CLASSES)
    model.load_state_dict(state, strict=True)
    model.to(device).eval()
    probabilities: list[np.ndarray] = []
    rows: list[np.ndarray] = []
    with torch.inference_mode():
        for features, index_t, _labels, row_indices in held_loader:
            logits = model(features.to(device, non_blocking=True), index_t.to(device, non_blocking=True))
            probabilities.append(torch.softmax(logits.float(), dim=1).cpu().numpy())
            rows.append(row_indices.numpy())
    actual_rows = np.concatenate(rows).astype(np.int64, copy=False)
    if not np.array_equal(actual_rows, expected_indices):
        raise RuntimeError(f'held row order drift during {name}')
    result = np.concatenate(probabilities).astype(np.float32, copy=False)
    check_probabilities(name, result, expected_indices.size)
    del model
    if device.type == 'cuda':
        torch.cuda.empty_cache()
    gc.collect()
    return result
